"""24px pixel-centre angles, clockwise from twelve, for the integer HUD sweep."""
from pathlib import Path
import math

ROOT = Path(__file__).resolve().parents[1]

def main():
    lines = ["#ifndef DOTA_ABILITY_ICON_MASK_H", "#define DOTA_ABILITY_ICON_MASK_H",
             "/* Generated by tools/prepare_ability_icon_mask.py; no runtime trig. */",
             "static const unsigned char ability_icon_angles[24*24]={"]
    for y in range(24):
        values = [int((math.atan2(x + .5 - 12, 12 - y - .5) % math.tau) * 256 / math.tau)
                  for x in range(24)]
        lines.append("    " + ",".join(map(str, values)) + ",")
    lines += ["};", "#endif", ""]
    (ROOT / "platform/ability_icon_mask.h").write_text("\n".join(lines), encoding="utf8")

if __name__ == "__main__":
    main()
